describe('Google OAuth Login', () => {
    beforeEach(() => {
        cy.visit('/login');
    });

    it('should log in successfully with valid Google account', () => {
        cy.get('button').contains('Log in with Google').click();
        cy.origin('https://accounts.google.com', () => {
            cy.get('input[type="email"]').type('validuser@gmail.com');
            cy.get('#identifierNext').click();
            cy.get('input[type="password"]').type('validpassword{enter}');
        });
        cy.url().should('include', '/dashboard');
        cy.get('.welcome-message').should('contain', 'Welcome, validuser!');
    });

    it('should show an error for invalid Google account', () => {
        cy.get('button').contains('Log in with Google').click();
        cy.origin('https://accounts.google.com', () => {
            cy.get('input[type="email"]').type('invaliduser@gmail.com');
            cy.get('#identifierNext').click();
            cy.get('input[type="password"]').type('invalidpassword{enter}');
        });
        cy.url().should('include', '/login');
        cy.get('.error-message').should('contain', 'Couldn’t sign you in');
    });
});
